#!/usr/bin/env python3
import json
from pathlib import Path
from datetime import datetime, timezone

ROOT = Path(__file__).resolve().parents[1]
ads = json.loads((ROOT / 'work/colaopeter/cp-adwords-daily-change-dashboard-2026-08-20.json').read_text())
ga = json.loads((ROOT / 'work/colaopeter/cp-adwords-landing-engagement-dashboard-2026-08-21.json').read_text())
if (ads['start_date'], ads['end_date']) != (ga['start_date'], ga['end_date']):
    raise SystemExit('Google Ads and GA4 reporting windows do not match')
start, end = ads['start_date'], ads['end_date']
rows = ads['metrics']
delivery = {'impressions':sum(x['impressions'] for x in rows),'clicks':sum(x['clicks'] for x in rows),'spend':round(sum(x['cost'] for x in rows),2),'conversions':sum(x['conversions'] for x in rows)}
delivery['ctr'] = delivery['clicks'] / delivery['impressions'] if delivery['impressions'] else 0
delivery['cpc'] = delivery['spend'] / delivery['clicks'] if delivery['clicks'] else 0
clicks = {x['visitorType']:x for x in ga['click_summary_rows']}
def readout(channel):
    x=ga['totals'].get(channel,{})
    c=clicks.get(channel,{})
    e=ga['event_totals'].get(channel,{})
    return {'sessions':x.get('sessions',0),'engaged_sessions':x.get('engagedSessions',0),'engagement_rate':x.get('engagementRate',0),'avg_session_seconds':x.get('averageSessionDuration',0),'contact_page_visits':e.get('contact_page_view',0),'phone_click_users':c.get('phoneClickUsers',0),'phone_clicks':c.get('phoneClicks',0),'form_starts':e.get('form_start',0),'form_submits':e.get('form_submit',0),'generate_lead_events':e.get('generate_lead',0),'key_events':x.get('keyEvents',0)}
paid, organic = readout('Paid Search'), readout('Organic Search')
payload={'generated_at':datetime.now(timezone.utc).isoformat(),'reporting_window':{'start_date':start,'end_date':end},'scope':{'campaigns':sorted({x['campaign'] for x in rows}),'landing_page':ga['landing_page'],'paid_channel':'Paid Search','organic_benchmark_channel':'Organic Search'},'delivery':delivery,'paid_search':paid,'organic_search_benchmark':organic,'definitions':{'engaged_session':'GA4 session lasting 10+ seconds, with a key event, or with 2+ page/screen views.','intent_actions':'Contact-page visits, phone-click users/events, and form starts are intent signals; they are not confirmed leads.','verified_lead':'Google Ads conversions and GA4 key events are shown separately. This window contains zero recorded Paid Search key events and zero Google Ads conversions.','organic_benchmark':'Organic Search uses the same landing-page filter and reporting window. Its small sample must not be treated as a performance trend.'},'source_files':['work/colaopeter/cp-adwords-daily-change-dashboard-2026-08-20.json','work/colaopeter/cp-adwords-landing-engagement-dashboard-2026-08-21.json']}
(ROOT/'work/colaopeter/cp-paid-search-funnel-dashboard.json').write_text(json.dumps(payload,indent=2)+'\n')
def n(x): return f'{x:,.0f}'
def money(x): return '$' + f'{x:,.2f}'
def pct(x): return f'{x*100:.1f}%'
def sec(x): return f'{x:.0f}s'
def metric(label,value,note,kind=''):
    return f'<article class="metric {kind}"><span>{label}</span><strong>{value}</strong><small>{note}</small></article>'
def action(label,key,note):
    return f'<tr><th>{label}</th><td>{n(paid[key])}</td><td>{n(organic[key])}</td><td>{note}</td></tr>'
body='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Colao & Peter | Paid Search Funnel</title><style>
:root{--ink:#152235;--muted:#607084;--paper:#f4f7fa;--card:#fff;--line:#dbe3eb;--paid:#0b698b;--organic:#6b8e23;--intent:#a65416}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Arial,sans-serif;line-height:1.45}main{max-width:1180px;margin:auto;padding:30px 20px 50px}a{color:#075a78}.crumb{font-size:14px;margin-bottom:20px}.crumb a{text-decoration:none}.eyebrow{color:var(--paid);font-weight:700;text-transform:uppercase;letter-spacing:.08em;font-size:12px}h1{font-size:clamp(28px,4vw,44px);line-height:1.08;margin:7px 0 10px}h2{font-size:22px;margin:0 0 12px}.lede{font-size:18px;max-width:900px;margin:0;color:#3e4d5e}.window{margin:18px 0 25px;color:var(--muted);font-weight:bold}.notice{background:#e7f3f7;border-left:4px solid var(--paid);padding:14px 16px;border-radius:4px;margin:22px 0 28px}.section{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:23px;margin:22px 0;box-shadow:0 1px 2px #1522350a}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric{border:1px solid var(--line);border-top:4px solid var(--paid);border-radius:7px;padding:14px;min-height:118px;background:#fff}.metric.intent{border-top-color:var(--intent)}.metric.organic{border-top-color:var(--organic)}.metric span{display:block;color:var(--muted);font-size:13px;font-weight:bold}.metric strong{font-size:29px;display:block;line-height:1.2;margin:7px 0 5px}.metric small{color:var(--muted);display:block;font-size:12px}.funnel{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.stage{padding:17px;border-radius:7px;color:#fff;background:var(--paid);min-height:150px}.stage:nth-child(2){background:#197d9e}.stage:nth-child(3){background:#398fae}.stage:nth-child(4){background:var(--intent)}.stage b{font-size:12px;letter-spacing:.06em;text-transform:uppercase;display:block}.stage strong{font-size:32px;display:block;margin:10px 0 4px}.stage span{font-size:13px;display:block}.split{display:grid;grid-template-columns:1fr 1fr;gap:20px}.compare{border:1px solid var(--line);border-radius:8px;padding:18px}.compare.paid{border-top:5px solid var(--paid)}.compare.organic{border-top:5px solid var(--organic)}.big{font-size:36px;font-weight:bold;margin:4px 0}.label{color:var(--muted);font-size:13px;font-weight:bold;text-transform:uppercase;letter-spacing:.04em}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:11px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}thead th{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.04em}.caveat{font-size:14px;background:#fff6e8;border-left:4px solid #ce8a32;padding:12px 14px;margin-top:16px}.definitions{font-size:14px;color:#4e5b69}.definitions li{margin:8px 0}@media(max-width:800px){main{padding:20px 13px}.grid,.funnel,.split{grid-template-columns:1fr 1fr}.section{padding:17px}}@media(max-width:520px){.grid,.funnel,.split{grid-template-columns:1fr}.metric{min-height:0}table{font-size:13px}th,td{padding:9px 5px}.table-wrap{overflow-x:auto}}
</style></head><body><main>
<div class="crumb"><a href="./">CP Web Performance Hub</a> / Paid Search Funnel</div><div class="eyebrow">Signature Care campaign decision view</div><h1>Paid Search: Delivery → Engagement → Intent</h1><p class="lede">A single decision surface for Google Ads delivery, what visitors do after landing, and the intent signals that occur before a verified lead. Organic Search is included only as the same-page benchmark.</p><p class="window">Reporting window: '''+start+''' through '''+end+''' · Landing-page filter: '''+ga['landing_page']+'''</p><div class="notice"><strong>Bottom line:</strong> delivery is real, but qualified conversion success is not proven. Paid Search generated '''+n(paid['sessions'])+''' landing sessions and '''+n(paid['engaged_sessions'])+''' engaged sessions; it recorded '''+n(delivery['conversions'])+''' Google Ads conversions and '''+n(paid['key_events'])+''' GA4 Paid Search key events.</div>
<section class="section"><h2>1. Ad delivery</h2><div class="grid">'''+metric('Impressions',n(delivery['impressions']),'Ads shown in search results')+metric('Clicks',n(delivery['clicks']),'Ad clicks; not the same measurement as GA4 sessions')+metric('Spend',money(delivery['spend']),'Google Ads cost')+metric('Cost per click',money(delivery['cpc']),pct(delivery['ctr'])+' click-through rate')+'''</div></section>
<section class="section"><h2>2. The paid-search funnel</h2><div class="funnel"><div class="stage"><b>Ads delivery</b><strong>'''+n(delivery['clicks'])+'''</strong><span>Google Ads clicks</span></div><div class="stage"><b>Landing sessions</b><strong>'''+n(paid['sessions'])+'''</strong><span>Paid Search GA4 sessions</span></div><div class="stage"><b>Engaged sessions</b><strong>'''+n(paid['engaged_sessions'])+'''</strong><span>'''+pct(paid['engagement_rate'])+''' engagement rate</span></div><div class="stage"><b>Verified results</b><strong>0</strong><span>Ads conversions and Paid Search GA4 key events</span></div></div><p class="caveat">Clicks and GA4 sessions are separate platform measurements and are intentionally not presented as a conversion rate. Google Ads clicks can differ from GA4 sessions because of consent, tagging, repeat clicks, and timing.</p></section>
<section class="section"><h2>3. Landing-page engagement</h2><div class="split"><div class="compare paid"><div class="label">Paid Search</div><div class="big">'''+pct(paid['engagement_rate'])+'''</div><div>'''+n(paid['engaged_sessions'])+''' engaged sessions of '''+n(paid['sessions'])+''' · '''+sec(paid['avg_session_seconds'])+''' average session duration</div></div><div class="compare organic"><div class="label">Organic Search benchmark</div><div class="big">'''+pct(organic['engagement_rate'])+'''</div><div>'''+n(organic['engaged_sessions'])+''' engaged sessions of '''+n(organic['sessions'])+''' · '''+sec(organic['avg_session_seconds'])+''' average session duration</div></div></div><p class="caveat">Organic Search had only '''+n(organic['sessions'])+''' landing sessions in this window. Its 100% engagement rate is too small to support a performance conclusion; it is context, not a target.</p></section>
<section class="section"><h2>4. Intent/actions before a verified lead</h2><div class="table-wrap"><table><thead><tr><th>Intent signal</th><th>Paid Search</th><th>Organic Search</th><th>What it means</th></tr></thead><tbody>'''+action('Contact Us page visits','contact_page_visits','Page-view events; not unique people or leads')+action('Phone-click users','phone_click_users','Distinct GA4 users who tapped the phone link')+action('Phone-click events','phone_clicks','Raw clicks; a user can click more than once')+action('Form starts','form_starts','Started forms; not submitted leads')+action('Form submissions','form_submits','Tracked events; not marked as GA4 key events in this window')+action('Generate-lead events','generate_lead_events','Not GA4 key events or Google Ads conversions; do not treat as verified leads')+'''</tbody></table></div></section>
<section class="section definitions"><h2>How to use this page</h2><ul><li><strong>Decision priority:</strong> fix or validate paid conversion tracking before changing budget or bidding based on upper-funnel volume.</li><li><strong>Engaged session:</strong> GA4 session lasting 10+ seconds, with a key event, or with 2+ page/screen views.</li><li><strong>Intent versus lead:</strong> Contact-page visits, phone-click users/events, and form starts are intent signals; they are not confirmed leads.</li><li><strong>Organic comparator:</strong> Organic Search uses the same landing-page filter and reporting window. Its small sample must not be treated as a performance trend.</li></ul></section><p class="definitions">Data sources: Google Ads daily delivery export and GA4 landing-page engagement export for the exact reporting window. Built '''+payload['generated_at'].split('T')[0]+'''.</p></main></body></html>'''
(ROOT/'work/colaopeter/cp-paid-search-funnel-dashboard.html').write_text(body)
print('Built funnel dashboard')
